from pathlib import Path
import html
import sys
from opportunity_content import build_opportunity_hub
from experience import enhance
from concept_story import build_concept_story

ROOT=Path(__file__).resolve().parent
PAGES=ROOT/'pages'
PAGES.mkdir(exist_ok=True)
PUBLISH = '--publish' in sys.argv

def link(text,url,kind='text-link'):
    return f'<a class="{kind}" href="{url}">{text}<span class="arrow" aria-hidden="true">↗</span></a>'

def render(name,title,description,body):
    body=enhance(name,body)
    home=name=='home'
    base='' if home else '../'
    targets=[('River Tech','river-tech'),('Tink Town','tink-town'),('Partnerships','partnerships'),('Investing','investing'),('Our story','story')]
    nav=''.join(f'<a href="{base}pages/{slug}.html"'+(' aria-current="page"' if name==slug else '')+f'>{label}</a>' for label,slug in [('River Tech','river-tech'),('Tink Town','tink-town'),('Investing','investing')])
    groups=[('Discover',[('River Tech','river-tech','Developing capable people'),('Tink Town','tink-town','Putting capability to work'),('Dream Big','dream-big','Find your people. Take your next step.')]),('Get involved',[('Partnerships','partnerships','Build something useful together'),('Church & Community','community','Shared faith. Local roots.'),('Investing','investing','Help build it here')]),('About',[('Our Story','story','The people and purpose'),('Contact','contact','Start a conversation')])]
    menu_groups=''.join('<section><h3>'+title+'</h3>'+''.join(f'<a href="{base}pages/{slug}.html"><span>{label}</span><small>{desc}</small></a>' for label,slug,desc in links)+'</section>' for title,links in groups)
    menu=f'<dialog id="site-menu" aria-labelledby="menu-title"><div class="menu-inner"><div class="menu-top"><span class="eyebrow">RIVER TECH · LLC</span><button type="button" class="menu-close" aria-label="Close menu">Close ×</button></div><h2 id="menu-title">Find your place.</h2><nav class="menu-groups" aria-label="All pages">{menu_groups}</nav><p class="menu-foot">Rooted in what matters. Ready for what comes next.</p></div></dialog>'
    footer=''.join(f'<a href="{base}pages/{slug}.html">{label}</a>' for label,slug in targets)
    footer+=f'<a href="{base}pages/community.html">Church &amp; Community</a><a href="{base}pages/dream-big.html">Dream Big</a>'
    robots = 'index,follow' if PUBLISH and name != '404' else 'noindex,nofollow'
    canonical = f'<link rel="canonical" href="https://rivertech.llc/{"" if home else "pages/"+name+".html"}">' if PUBLISH and name != '404' else ''
    out=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)} | River Tech LLC</title><meta name="description" content="{html.escape(description,quote=True)}">
<meta name="robots" content="{robots}">{canonical}<meta name="theme-color" content="#104472">
<link rel="icon" href="{base}assets/images/mark.svg"><link rel="stylesheet" href="{base}assets/css/redesign.css?v=20261024-readable">
<script src="{base}assets/js/redesign.js?v=20261024-readable" defer></script></head><body data-page="{name}">
<a class="skip" href="#main">Skip to content</a>
<header class="site-header"><div class="wrap header-inner"><a class="wordmark" href="{base}index.html" aria-label="River Tech LLC home">RIVER TECH <span>· LLC</span></a><nav class="primary-links" aria-label="Main navigation">{nav}</nav><button class="site-menu-toggle" type="button" aria-haspopup="dialog" aria-controls="site-menu" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button></div></header>
{menu}
<main id="main">{body}</main>
<footer class="footer"><div class="wrap"><div class="footer-top"><div><a class="wordmark" href="{base}index.html">RIVER TECH <span>· LLC</span></a><p>Two sister brands. A shared commitment to capable people and practical enterprise.</p></div><nav class="footer-links" aria-label="Footer navigation">{footer}<a href="{base}pages/contact.html">Contact</a><a href="{base}pages/river-tech.html#schools">Current schools</a></nav></div><div class="footer-base"><span>© 2026 River Tech LLC · Idaho</span><span>River Tech and Tink Town are brands of River Tech LLC.</span><a href="{base}pages/policies.html">Policies & privacy</a></div></div></footer>
</body></html>'''
    (ROOT/'index.html' if home else PAGES/f'{name}.html').write_text(out)

def hero(kicker,title,desc,blue=False,actions=''):
    return f'<section class="page-hero{" blue" if blue else ""}"><div class="wrap"><span class="eyebrow{" light" if blue else ""}">{kicker}</span><h1>{title}</h1><p class="lead">{desc}</p>{f"<div class=hero-actions>{actions}</div>" if actions else ""}</div></section>'

def cta(title,text='Start a conversation',url='contact.html'):
    return f'<section class="cta-section"><div class="wrap cta-inner"><h2>{title}</h2>{link(text,url,"button white")}</div></section>'

def tabs(prefix,labels,panels):
    buttons=''.join(f'<button class="route-tab" role="tab" id="{prefix}-tab-{i}" aria-controls="{prefix}-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" type="button">{label}</button>' for i,label in enumerate(labels))
    content=''.join(f'<section class="route-panel" id="{prefix}-panel-{i}" role="tabpanel" aria-labelledby="{prefix}-tab-{i}"'+(' hidden' if i else '')+f'>{p}</section>' for i,p in enumerate(panels))
    return f'<div data-tabs><div class="route-tabs" role="tablist" aria-label="{prefix.replace("-"," ")}">{buttons}</div>{content}</div>'

